// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address possibleOwner) public {
        address ownerCandidate = possibleOwner;

        vm.prank(ownerCandidate);
        c.initialize();

        address reportedOwner;
        try c.owner() returns (address o) {
            reportedOwner = o;
        } catch {
            reportedOwner = address(0);
        }

        assertTrue(reportedOwner == ownerCandidate);
    }
}
